function getSpeechRecognitionConstructor() {
  if (typeof window === 'undefined') {
    return null;
  }

  return (
    window.SpeechRecognition ||
    window.webkitSpeechRecognition ||
    null
  );
}

export function isSpeechRecognitionSupported() {
  return Boolean(getSpeechRecognitionConstructor());
}

export function createRecognizer(options = {}) {
  const SpeechRecognition = getSpeechRecognitionConstructor();

  if (!SpeechRecognition) {
    return null;
  }

  const recognizer = new SpeechRecognition();

  if (options.lang) {
    recognizer.lang = options.lang;
  }

  if (typeof options.interimResults === 'boolean') {
    recognizer.interimResults = options.interimResults;
  }

  if (typeof options.continuous === 'boolean') {
    recognizer.continuous = options.continuous;
  }

  if (typeof options.maxAlternatives === 'number') {
    recognizer.maxAlternatives = options.maxAlternatives;
  }

  return recognizer;
}

export function isSpeechSynthesisSupported() {
  return (
    typeof window !== 'undefined' &&
    'speechSynthesis' in window
  );
}

export function speak(text, options = {}) {
  if (!isSpeechSynthesisSupported() || !text?.trim()) {
    return false;
  }

  window.speechSynthesis.cancel();

  const utterance = new SpeechSynthesisUtterance(text);

  if (options.lang) {
    utterance.lang = options.lang;
  } else {
    utterance.lang = 'en-AU';
  }

  if (typeof options.rate === 'number') {
    utterance.rate = options.rate;
  }

  if (typeof options.pitch === 'number') {
    utterance.pitch = options.pitch;
  }

  if (typeof options.volume === 'number') {
    utterance.volume = options.volume;
  }

  window.speechSynthesis.speak(utterance);

  return true;
}

export function stopSpeaking() {
  if (isSpeechSynthesisSupported()) {
    window.speechSynthesis.cancel();
  }
}

export default {
  isSpeechRecognitionSupported,
  isSpeechSynthesisSupported,
  createRecognizer,
  speak,
  stopSpeaking,
};
